-- Read-only projection of this module's tables for the AI analyst (aiquery).

CREATE OR REPLACE VIEW `ai_employees` AS select `hr_employees`.`id` AS `id`,`hr_employees`.`owner_id` AS `owner_id`,`hr_employees`.`first_name` AS `first_name`,`hr_employees`.`last_name` AS `last_name`,`hr_employees`.`email` AS `email`,`hr_employees`.`department_id` AS `department_id`,`hr_employees`.`location_id` AS `location_id`,`hr_employees`.`employment_type` AS `employment_type`,`hr_employees`.`status` AS `status`,`hr_employees`.`salary` AS `salary`,`hr_employees`.`hourly_rate` AS `hourly_rate`,`hr_employees`.`overtime_rate` AS `overtime_rate`,`hr_employees`.`start_date` AS `start_date`,`hr_employees`.`end_date` AS `end_date`,`hr_employees`.`created_at` AS `created_at`,`hr_employees`.`updated_at` AS `updated_at` from `hr_employees`;
